DATA["所以"] = [==[so; therefore]==]
DATA["打法"] = [==[approach; playbook; strategy]==]
DATA["抓手"] = [==[grip; lever; (fig.) means to get things done]==]
DATA["拆解"] = [==[to break down; to disassemble]==]
DATA["摸鱼"] = [==[to slack off; to goof off]==]
DATA["时候"] = [==[time; moment]==]
DATA["时间"] = [==[time]==]
DATA["明天"] = [==[tomorrow]==]
DATA["昨天"] = [==[yesterday]==]
DATA["是"] = [==[to be; is; yes]==]
DATA["有"] = [==[to have; there is]==]
DATA["来"] = [==[to come]==]
DATA["没"] = [==[not; haven't]==]
DATA["涨薪"] = [==[to get a raise; pay rise]==]
DATA["点"] = [==[point; dot; a bit]==]
DATA["然后"] = [==[then; after that]==]
DATA["环比"] = [==[month-on-month; quarter-on-quarter]==]
DATA["现在"] = [==[now]==]
DATA["的"] = [==[of; 's]==]
DATA["看"] = [==[to look; to see]==]
DATA["能"] = [==[can; to be able to]==]
DATA["落地"] = [==[to land; to be implemented]==]
DATA["行"] = [==[OK; to be fine]==]
DATA["要"] = [==[to want; to need]==]
DATA["说"] = [==[to say; to speak]==]
DATA["请"] = [==[please; to invite]==]
DATA["谢谢"] = [==[thank you]==]
DATA["走"] = [==[to walk; to leave]==]
DATA["躺平"] = [==[to lie flat; to opt out of the rat race]==]
DATA["这"] = [==[this]==]
DATA["这个"] = [==[this one]==]
DATA["那"] = [==[that]==]
DATA["那个"] = [==[that one]==]
DATA["链路"] = [==[chain; pipeline; link]==]
DATA["问题"] = [==[problem; question]==]
DATA["靠谱"] = [==[reliable]==]

local M = {}

-- 命中词表才写英文释义；其它候选（英文、数字、emoji）原样放行
function M.func(input)
    for cand in input:iter() do
        local g = DATA[cand.text]
        if g then cand:get_genuine().comment = g end
        yield(cand)
    end
end

return M
